package com.successor.engine.model;

/** Where a player-season's numbers came from. */
public enum Source {
    /** Per-game minutes, goals, assists, cards (2012/13–2025/26). */
    TRANSFERMARKT,
    /** xG, xA, shots, key passes, xGChain, xGBuildup (2014/15–2023/24). */
    UNDERSTAT,
    /** FBref's Opta / StatsBomb profile incl. defensive and progression stats (2017/18–2024/25). */
    FBREF,
    /** Basic stats only (2025/26). */
    FBREF_BASIC,
    /** 2025/26 Big 5: Understat xG, xA, xGChain, key passes and Sofascore defending, carrying, passing. */
    SOFASCORE,
    /** Generated by {@code SyntheticData} for tests, benchmarks and the offline sample. */
    SYNTHETIC
}
